-- Drop and recreate sheffield_clubs table with correct schema
DROP TABLE IF EXISTS sheffield_clubs;

CREATE TABLE sheffield_clubs (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    short_name TEXT,
    founded_year INTEGER,
    ground_name TEXT,
    ground_capacity INTEGER,
    city TEXT,
    region TEXT,
    primary_color TEXT,
    secondary_color TEXT,
    origin TEXT
);

-- Insert all 187 Sheffield clubs

SELECT COUNT(*) as total_clubs FROM sheffield_clubs;
